sp_widget.css:
.trackmed-widget {
    margin-bottom: 30px;
    width: 100%;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.stat-card {
  background: #fff;
  border-radius: 14px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  border-left: 4px solid transparent;
  transition: all .25s ease;
}

.stat-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
}

.stat-card.stat-blue {
  border-left-color: #1a73e8;
}

.stat-card.stat-green {
  border-left-color: #22c55e;
}

.stat-card.stat-purple {
  border-left-color: #8b5cf6;
}

.stat-card.stat-orange {
  border-left-color: #f97316;
}

.stat-card.stat-teal {
  border-left-color: #06b6d4;
}

.stat-icon-wrap {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 20px;
  flex-shrink: 0;
}

.blue-icon {
  background: #dbeafe;
  color: #1a73e8;
}

.green-icon {
  background: #dcfce7;
  color: #22c55e;
}

.purple-icon {
  background: #ede9fe;
  color: #8b5cf6;
}

.orange-icon {
  background: #ffedd5;
  color: #f97316;
}

.teal-icon {
  background: #cffafe;
  color: #06b6d4;
}

.stat-info {
  flex: 1;
}

.stat-label {
  font-size: 12px;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 500;
  letter-spacing: .5px;
}

.stat-value {
  font-size: 28px;
  font-weight: 800;
  color: #1a2332;
  margin-top: 4px;
  margin-bottom: 4px;
}

.stat-change {
  font-size: 12px;
  font-weight: 600;
}

.stat-change.positive {
  color: #22c55e;
}

.stat-change.negative {
  color: #ef4444;
}

.stat-sub {
  font-size: 12px;
  color: #22c55e;
  font-weight: 600;
}

@media(max-width:1200px){

  .stats-row{
    grid-template-columns:repeat(3,1fr);
  }

}

@media(max-width:768px){

  .stats-row{
    grid-template-columns:repeat(1,1fr);
  }

}

